<?php
declare(strict_types=1);
namespace Hls\Controllers;
use Hls\Http\View;
use Hls\Repositories\Repository;
use Hls\Middleware\Access;
use Hls\Services\Audit;
use Hls\Http\Input;
use Hls\Http\HttpError;
final class FinanceController {
 public function __construct(private Repository $repo, private View $view, private Access $access, private Audit $audit) {}
 public function accounts(): void {
  $this->access->demand('finance.account.view'); $error=null;
  if ($_SERVER['REQUEST_METHOD']==='POST') { $action=Input::text($_POST,'action',12,false) ?: 'save'; try { $this->access->demand('finance.account.manage'); $id=Input::id($_POST,'id',true); $branch=Input::id($_POST,'branch_id'); $this->access->demandBranch($branch); $code=strtoupper(Input::text($_POST,'code',40)); if(!preg_match('/^[A-Z0-9_-]+$/D',$code)) throw new HttpError(422,'Kode rekening tidak valid.'); $name=Input::text($_POST,'name',160); $type=Input::text($_POST,'account_type',4); if(!in_array($type,['CASH','BANK'],true)) throw new HttpError(422,'Jenis rekening tidak valid.'); $currency=strtoupper(Input::text($_POST,'currency',3)); if(!preg_match('/^[A-Z]{3}$/D',$currency)) throw new HttpError(422,'Mata uang tidak valid.'); $active=Input::flag($_POST,'active');
    if($action==='status'){$id=Input::id($_POST,'id');$active=Input::flag($_POST,'active');$row=$this->repo->one('SELECT * FROM fin_accounts WHERE id=?',[$id]);if(!$row)throw new HttpError(404,'Rekening tidak ditemukan.');$this->access->demandBranch((int)$row['branch_id']);$this->repo->run('UPDATE fin_accounts SET active=?,version=version+1,updated_at=NOW() WHERE id=? AND version=?',[$active,$id,Input::id($_POST,'version')]);$this->audit->record((int)$this->access->user['id'],'finance_account_status','fin_accounts',$id,['active'=>$active]);}
    elseif($id){$row=$this->repo->one('SELECT * FROM fin_accounts WHERE id=?',[$id]);if(!$row)throw new HttpError(404,'Rekening tidak ditemukan.');if((int)$row['branch_id']!==$branch)throw new HttpError(422,'Cabang rekening tidak dapat dipindahkan.');$this->repo->run('UPDATE fin_accounts SET code=?,name=?,account_type=?,currency=?,active=?,version=version+1,updated_at=NOW() WHERE id=? AND version=?',[$code,$name,$type,$currency,$active,$id,Input::id($_POST,'version')]);$this->audit->record((int)$this->access->user['id'],'finance_account_updated','fin_accounts',$id,['code'=>$code]);}
    else{$this->repo->run('INSERT INTO fin_accounts(branch_id,code,name,account_type,currency,active,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,NOW(),NOW())',[$branch,$code,$name,$type,$currency,$active,$this->access->user['id']]);$id=(int)$this->repo->db->lastInsertId();$this->audit->record((int)$this->access->user['id'],'finance_account_created','fin_accounts',$id,['code'=>$code]);}
    $_SESSION['flash']='Rekening berhasil disimpan.';$this->view->redirect('/finance/accounts'); } catch(HttpError $e){$error=$e->getMessage();} catch(\PDOException $e){if($e->getCode()!=='23000')throw $e;$error='Kode rekening sudah digunakan pada cabang tersebut.';}}
  $rows=$this->repo->all('SELECT a.*,b.name branch_name,COALESCE((SELECT SUM(l.debit-l.credit) FROM fin_cash_ledger l WHERE l.account_id=a.id),0) balance FROM fin_accounts a JOIN branches b ON b.id=a.branch_id WHERE a.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY a.code',[$this->access->user['id'],$this->access->user['all_branches']]);$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1 ORDER BY code');$this->view->render('finance-accounts',['title'=>'Kas & Bank','rows'=>$rows,'branches'=>$branches,'error'=>$error]); }

 public function expenses(): void { $this->access->demand('finance.expense.view'); $error=null; if($_SERVER['REQUEST_METHOD']==='POST'){ $this->access->demand('finance.expense.create'); $branch=Input::id($_POST,'branch_id'); $this->access->demandBranch($branch); $category=Input::id($_POST,'category_id'); $account=Input::id($_POST,'account_id'); $date=Input::text($_POST,'expense_date',10); $amount=(float)($_POST['amount']??0); $ref=trim((string)($_POST['reference']??'')); $desc=trim((string)($_POST['description']??'')); if($amount<=0||$ref==='') throw new HttpError(422,'Referensi dan nominal wajib valid.'); if(!$this->repo->one('SELECT id FROM fin_accounts WHERE id=? AND branch_id=? AND active=1',[$account,$branch])||!$this->repo->one('SELECT id FROM fin_expense_categories WHERE id=? AND active=1',[$category])) throw new HttpError(422,'Rekening atau kategori tidak tersedia.'); $this->repo->db->beginTransaction(); try{$this->repo->run('INSERT INTO fin_expenses(branch_id,category_id,account_id,expense_date,amount,status,description,created_by,created_at,updated_at) VALUES(?,?,?,?,?,"POSTED",?,?,NOW(),NOW())',[$branch,$category,$account,$date,$amount,$desc?:$ref,$this->access->user['id']]);$id=(int)$this->repo->db->lastInsertId();$this->repo->run('INSERT INTO fin_cash_ledger(branch_id,account_id,transaction_type,reference_type,reference_id,transaction_date,debit,credit,note,created_by,created_at) VALUES(?, ?,"EXPENSE","EXPENSE",?,?,0,?,?,?,NOW())',[$branch,$account,$id,$date,$amount,$ref,$this->access->user['id']]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_expense_posted','fin_expenses',$id,['amount'=>$amount,'reference'=>$ref]);$this->view->redirect('/finance/expenses');}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}}$rows=$this->repo->all('SELECT e.*,c.code category_code,a.code account_code,b.name branch_name FROM fin_expenses e JOIN fin_expense_categories c ON c.id=e.category_id JOIN fin_accounts a ON a.id=e.account_id JOIN branches b ON b.id=e.branch_id WHERE e.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY e.id DESC',[$this->access->user['id'],$this->access->user['all_branches']]);$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1');$categories=$this->repo->all('SELECT id,code,name FROM fin_expense_categories WHERE active=1 ORDER BY code');$accounts=$this->repo->all('SELECT id,branch_id,code,name FROM fin_accounts WHERE active=1');$this->view->render('finance-expenses',['title'=>'Pengeluaran','rows'=>$rows,'branches'=>$branches,'categories'=>$categories,'accounts'=>$accounts,'error'=>$error]); }
 public function categories():void{$this->access->demand('finance.category.view');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){ $this->access->demand('finance.category.manage');$code=strtoupper(trim((string)($_POST['code']??'')));$name=trim((string)($_POST['name']??''));if(!preg_match('/^[A-Z0-9_-]+$/D',$code)||$name==='')throw new HttpError(422,'Kode dan nama kategori wajib valid.');try{$this->repo->run('INSERT INTO fin_expense_categories(code,name,active,created_at,updated_at) VALUES(?,?,1,NOW(),NOW())',[$code,$name]);$this->audit->record((int)$this->access->user['id'],'finance_category_created','fin_expense_categories',(int)$this->repo->db->lastInsertId(),['code'=>$code]);$this->view->redirect('/finance/expense-categories');}catch(\PDOException $e){if($e->getCode()==='23000')$error='Kode kategori sudah digunakan.';else throw $e;}}$rows=$this->repo->all('SELECT * FROM fin_expense_categories ORDER BY code');$this->view->render('finance-categories',['title'=>'Kategori Pengeluaran','rows'=>$rows,'error'=>$error]);}
 public function invoices():void{$this->access->demand('finance.invoice.view');$rows=$this->repo->all('SELECT i.*,c.name customer_name,b.name branch_name FROM fin_invoices i JOIN md_customers c ON c.id=i.customer_id JOIN branches b ON b.id=i.branch_id WHERE i.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY i.id DESC',[$this->access->user['id'],$this->access->user['all_branches']]);$this->view->render('finance-invoices',['title'=>'Invoice','rows'=>$rows,'branches'=>[],'customers'=>[],'error'=>null]);}
 public function dashboard():void{$this->access->demand('finance.account.view');$start=trim((string)($_GET['start']??date('Y-m-01')));$end=trim((string)($_GET['end']??date('Y-m-d')));$branch=(int)($_GET['branch_id']??0);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)||$start>$end)throw new HttpError(422,'Periode tidak valid.');if($branch)$this->access->demandBranch($branch);$scope=' IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1)';$scopeArgs=[$this->access->user['id'],$this->access->user['all_branches']];$branchSql=$branch?' AND branch_id=?':'';$branchArgs=$branch?[$branch]:[];$balance=(float)($this->repo->one('SELECT COALESCE(SUM(debit-credit),0) total FROM fin_cash_ledger WHERE branch_id'.$scope,$scopeArgs)['total']??0);$receivable=(float)($this->repo->one('SELECT COALESCE(SUM(i.total_amount-COALESCE((SELECT SUM(pa.amount) FROM fin_payment_allocations pa JOIN fin_payments p ON p.id=pa.payment_id WHERE pa.invoice_id=i.id AND p.status="POSTED"),0)),0) total FROM fin_invoices i WHERE i.status IN ("ISSUED","PARTIALLY_PAID") AND i.branch_id'.$scope,$scopeArgs)['total']??0);$payable=(float)($this->repo->one('SELECT COALESCE(SUM(b.total_amount-COALESCE((SELECT SUM(p.amount) FROM fin_supplier_payments p WHERE p.bill_id=b.id AND p.status="POSTED"),0)),0) total FROM fin_supplier_bills b WHERE b.status IN ("POSTED","PARTIALLY_PAID") AND b.branch_id'.$scope,$scopeArgs)['total']??0);$in=(float)($this->repo->one('SELECT COALESCE(SUM(debit),0) total FROM fin_cash_ledger WHERE transaction_type="RECEIPT" AND transaction_date BETWEEN ? AND ? AND branch_id'.$scope,$start,$end,...$scopeArgs)['total']??0);$out=(float)($this->repo->one('SELECT COALESCE(SUM(credit),0) total FROM fin_cash_ledger WHERE transaction_type IN ("EXPENSE","PAYMENT") AND transaction_date BETWEEN ? AND ? AND branch_id'.$scope,$start,$end,...$scopeArgs)['total']??0);$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1 ORDER BY code');$this->view->render('finance-dashboard',['title'=>'Dashboard Keuangan','start'=>$start,'end'=>$end,'branch_id'=>$branch,'branches'=>$branches,'balance'=>$balance,'receivable'=>$receivable,'payable'=>$payable,'inflow'=>$in,'outflow'=>$out]);}
 public function profitLoss():void{$this->access->demand('finance.account.view');$start=(string)($_GET['start']??date('Y-m-01'));$end=(string)($_GET['end']??date('Y-m-d'));$branch=(int)($_GET['branch_id']??0);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)||$start>$end)throw new HttpError(422,'Periode tidak valid.');if($branch)$this->access->demandBranch($branch);$filter=$branch?' AND i.branch_id=?':' AND i.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1)';$args=$branch?[$branch]:[$this->access->user['id'],$this->access->user['all_branches']];$revenue=$this->repo->all('SELECT "Invoice customer" category,SUM(i.total_amount) amount FROM fin_invoices i WHERE i.status IN ("ISSUED","PARTIALLY_PAID","PAID") AND i.invoice_date BETWEEN ? AND ?'.$filter.' GROUP BY category',[$start,$end,...$args]);$expenseFilter=$branch?' AND e.branch_id=?':' AND e.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1)';$expenseArgs=$branch?[$branch]:[$this->access->user['id'],$this->access->user['all_branches']];$expenses=$this->repo->all('SELECT c.name category,SUM(e.amount) amount FROM fin_expenses e JOIN fin_expense_categories c ON c.id=e.category_id WHERE e.status="POSTED" AND e.expense_date BETWEEN ? AND ?'.$expenseFilter.' GROUP BY c.id,c.name ORDER BY c.name',[$start,$end,...$expenseArgs]);$income=array_sum(array_column($revenue,'amount'));$cost=array_sum(array_column($expenses,'amount'));$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1 ORDER BY code');$this->view->render('finance-profit-loss',['title'=>'Laba/Rugi','start'=>$start,'end'=>$end,'branch_id'=>$branch,'branches'=>$branches,'revenue'=>$revenue,'expenses'=>$expenses,'income'=>$income,'cost'=>$cost,'net'=>$income-$cost,'margin'=>$income>0?(($income-$cost)/$income*100):null]);}}